@Test
public void testTx() {
    rtx.set(Bytes.of("r1"), new Column("cf1"), Bytes.of("v1"));
    rtx.set(Bytes.of("r2"), new Column("cf2", "cq2"), Bytes.of("v2"));
    rtx.delete(Bytes.of("r3"), new Column("cf3"));
    expect(tx.get(Bytes.of("r4"), new Column("cf4"))).andReturn(Bytes.of("v4"));
    replay(tx);
    rtx.get(Bytes.of("r4"), new Column("cf4"));
    List<LogEntry> entries = rtx.getTxLog().getLogEntries();
    Assert.assertEquals(4, entries.size());
    Assert.assertEquals("LogEntry{op=SET, row=r1, col=cf1  , value=v1}", entries.get(0).toString());
    Assert.assertEquals("LogEntry{op=SET, row=r2, col=cf2 cq2 , value=v2}", entries.get(1).toString());
    Assert.assertEquals("LogEntry{op=DELETE, row=r3, col=cf3  , value=}", entries.get(2).toString());
    Assert.assertEquals("LogEntry{op=GET, row=r4, col=cf4  , value=v4}", entries.get(3).toString());
    Assert.assertEquals("{r4 cf4  =v4}", rtx.getTxLog().getOperationMap(LogEntry.Operation.GET).toString());
    Assert.assertEquals("{r2 cf2 cq2 =v2, r1 cf1  =v1}", rtx.getTxLog().getOperationMap(LogEntry.Operation.SET).toString());
    Assert.assertEquals("{r3 cf3  =}", rtx.getTxLog().getOperationMap(LogEntry.Operation.DELETE).toString());
}

